package org.apache.lucene.queries.intervals;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.apache.lucene.analysis.CachingTokenFilter;
import org.apache.lucene.analysis.TokenStream;
import org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute;
import org.apache.lucene.analysis.tokenattributes.PositionLengthAttribute;
import org.apache.lucene.analysis.tokenattributes.TermToBytesRefAttribute;
import org.apache.lucene.index.LeafReaderContext;
import org.apache.lucene.search.BooleanQuery;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.QueryVisitor;
import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.graph.GraphTokenStreamFiniteStrings;

/**
 * Constructs an {@link IntervalsSource} based on analyzed text.
 *
 * <p>Code adopted from ASL-licensed <a
 * href="https://github.com/elastic/elasticsearch">Elasticsearch</a>.
 *
 * @see
 *     "https://github.com/elastic/elasticsearch/blob/7.10/server/src/main/java/org/elasticsearch/index/query/IntervalBuilder.java"
 */
final class IntervalBuilder {
  static IntervalsSource analyzeText(CachingTokenFilter stream, int maxGaps, boolean ordered)
      throws IOException {
    assert stream != null;

    TermToBytesRefAttribute termAtt = stream.getAttribute(TermToBytesRefAttribute.class);
    PositionIncrementAttribute posIncAtt = stream.addAttribute(PositionIncrementAttribute.class);
    PositionLengthAttribute posLenAtt = stream.addAttribute(PositionLengthAttribute.class);

    if (termAtt == null) {
      return NO_INTERVALS;
    }

    int numTokens = 0;
    boolean hasSynonyms = false;
    boolean isGraph = false;

    stream.reset();
    while (stream.incrementToken()) {
      numTokens++;
      int positionIncrement = posIncAtt.getPositionIncrement();
      if (positionIncrement == 0) {
        hasSynonyms = true;
      }
      int positionLength = posLenAtt.getPositionLength();
      if (positionLength > 1) {
        isGraph = true;
      }
    }

    if (numTokens == 0) {
      return NO_INTERVALS;
    }

    if (numTokens == 1) {
      TermToBytesRefAttribute bytesAtt = stream.addAttribute(TermToBytesRefAttribute.class);
      stream.reset();
      stream.incrementToken();
      return new TermIntervalsSource(BytesRef.deepCopyOf(bytesAtt.getBytesRef()));
    }

    List<IntervalsSource> assembled = new ArrayList<>();
    if (isGraph) {
      stream.reset();
      GraphTokenStreamFiniteStrings graph = new GraphTokenStreamFiniteStrings(stream);
      int[] articulationPoints = graph.articulationPoints();
      int lastState = 0;
      int maxClauseCount = BooleanQuery.getMaxClauseCount();
      for (int i = 0; i <= articulationPoints.length; i++) {
        int start = lastState;
        int end = -1;
        if (i < articulationPoints.length) {
          end = articulationPoints[i];
        }
        lastState = end;
        if (graph.hasSidePath(start)) {
          List<IntervalsSource> paths = new ArrayList<>();
          Iterator<TokenStream> finiteStrings = graph.getFiniteStrings(start, end);
          while (finiteStrings.hasNext()) {
            TokenStream ts = finiteStrings.next();
            List<IntervalsSource> pathTerms = new ArrayList<>();
            TermToBytesRefAttribute bytesAtt = ts.addAttribute(TermToBytesRefAttribute.class);
            PositionIncrementAttribute posAtt = ts.addAttribute(PositionIncrementAttribute.class);
            ts.reset();
            while (ts.incrementToken()) {
              BytesRef term = BytesRef.deepCopyOf(bytesAtt.getBytesRef());
              int increment = posAtt.getPositionIncrement();
              if (increment > 1) {
                int precedingSpaces = increment - 1;
                IntervalsSource termSource = new TermIntervalsSource(term);
                if (precedingSpaces == 1) {
                  pathTerms.add(new ExtendedIntervalsSource(termSource, 1, 0));
                } else {
                  pathTerms.add(new ExtendedIntervalsSource(termSource, precedingSpaces, 0));
                }
              } else if (increment == 1) {
                pathTerms.add(new TermIntervalsSource(term));
              } else {
                pathTerms.add(
                    new ExtendedIntervalsSource(
                        new TermIntervalsSource(term), increment - 1, 0));
              }
            }
            ts.end();
            IntervalsSource phrase;
            if (pathTerms.size() == 0) {
              phrase = NO_INTERVALS;
            } else if (pathTerms.size() == 1) {
              phrase = pathTerms.get(0);
            } else {
              List<List<IntervalsSource>> rewritten = new ArrayList<>();
              rewritten.add(new ArrayList<>());
              for (int sourceIndex = 0; sourceIndex < pathTerms.size(); sourceIndex++) {
                IntervalsSource src = pathTerms.get(sourceIndex);
                List<IntervalsSource> singletons = new ArrayList<>();
                List<IntervalsSource> nonSingletons = new ArrayList<>();
                for (IntervalsSource disj : src.pullUpDisjunctions()) {
                  if (disj.minExtent() == 1) {
                    singletons.add(disj);
                  } else {
                    nonSingletons.add(disj);
                  }
                }
                List<IntervalsSource> disjuncts = new ArrayList<>();
                if (singletons.size() > 0) {
                  disjuncts.add(DisjunctionIntervalsSource.create(singletons, true));
                }
                for (int ns = 0; ns < nonSingletons.size(); ns++) {
                  disjuncts.add(nonSingletons.get(ns));
                }
                if (disjuncts.size() == 1) {
                  IntervalsSource only = disjuncts.get(0);
                  for (int r = 0; r < rewritten.size(); r++) {
                    rewritten.get(r).add(only);
                  }
                  continue;
                }
                if (rewritten.size() * disjuncts.size() > IndexSearcher.getMaxClauseCount()) {
                  throw new IllegalArgumentException("Too many disjunctions to expand");
                }
                List<List<IntervalsSource>> toAdd = new ArrayList<>();
                for (int d = 0; d < disjuncts.size(); d++) {
                  IntervalsSource disj = disjuncts.get(d);
                  for (int r = 0; r < rewritten.size(); r++) {
                    List<IntervalsSource> copy = new ArrayList<>(rewritten.get(r));
                    copy.add(disj);
                    toAdd.add(copy);
                  }
                }
                rewritten = toAdd;
              }
              List<IntervalsSource> pulled = new ArrayList<>();
              for (int r = 0; r < rewritten.size(); r++) {
                List<IntervalsSource> group = rewritten.get(r);
                if (group.size() == 1) {
                  pulled.add(group.get(0));
                } else {
                  pulled.add(new BlockIntervalsSource(group));
                }
              }
              if (pulled.size() == 1) {
                phrase = pulled.get(0);
              } else {
                phrase = DisjunctionIntervalsSource.create(pulled, true);
              }
            }
            if (paths.size() >= maxClauseCount) {
              throw new BooleanQuery.TooManyClauses();
            }
            paths.add(phrase);
          }
          if (paths.size() > 0) {
            assembled.add(DisjunctionIntervalsSource.create(paths, true));
          }
        } else {
          Iterator<TokenStream> finiteStrings = graph.getFiniteStrings(start, end);
          TokenStream ts = finiteStrings.next();
          TermToBytesRefAttribute bytesAtt = ts.addAttribute(TermToBytesRefAttribute.class);
          PositionIncrementAttribute posAtt = ts.addAttribute(PositionIncrementAttribute.class);
          ts.reset();
          while (ts.incrementToken()) {
            BytesRef term = BytesRef.deepCopyOf(bytesAtt.getBytesRef());
            int increment = posAtt.getPositionIncrement();
            if (increment > 1) {
              int precedingSpaces = increment - 1;
              if (precedingSpaces == 1) {
                assembled.add(new ExtendedIntervalsSource(new TermIntervalsSource(term), 1, 0));
              } else {
                assembled.add(
                    new ExtendedIntervalsSource(
                        new TermIntervalsSource(term), precedingSpaces, 0));
              }
            } else if (increment == 1) {
              assembled.add(new TermIntervalsSource(term));
            } else {
              assembled.add(
                  new ExtendedIntervalsSource(
                      new TermIntervalsSource(term), increment - 1, 0));
            }
          }
          ts.end();
          assert finiteStrings.hasNext() == false;
        }
      }
    } else if (hasSynonyms) {
      List<IntervalsSource> synonyms = new ArrayList<>();
      TermToBytesRefAttribute bytesAtt = stream.addAttribute(TermToBytesRefAttribute.class);
      PositionIncrementAttribute posAtt = stream.addAttribute(PositionIncrementAttribute.class);
      stream.reset();
      int spaces = 0;
      while (stream.incrementToken()) {
        int posInc = posAtt.getPositionIncrement();
        if (posInc > 0) {
          if (synonyms.size() == 1) {
            IntervalsSource only = synonyms.get(0);
            if (spaces == 0) {
              assembled.add(only);
            } else {
              assembled.add(new ExtendedIntervalsSource(only, spaces, 0));
            }
          } else if (synonyms.size() > 1) {
            IntervalsSource orSource = DisjunctionIntervalsSource.create(synonyms, true);
            if (spaces == 0) {
              assembled.add(orSource);
            } else {
              assembled.add(new ExtendedIntervalsSource(orSource, spaces, 0));
            }
          }
          synonyms = new ArrayList<>();
          spaces = posInc - 1;
        }
        synonyms.add(new TermIntervalsSource(BytesRef.deepCopyOf(bytesAtt.getBytesRef())));
      }
      if (synonyms.size() == 1) {
        IntervalsSource only = synonyms.get(0);
        if (spaces == 0) {
          assembled.add(only);
        } else {
          assembled.add(new ExtendedIntervalsSource(only, spaces, 0));
        }
      } else {
        IntervalsSource orSource = DisjunctionIntervalsSource.create(synonyms, true);
        if (spaces == 0) {
          assembled.add(orSource);
        } else {
          assembled.add(new ExtendedIntervalsSource(orSource, spaces, 0));
        }
      }
    } else {
      TermToBytesRefAttribute bytesAtt = stream.addAttribute(TermToBytesRefAttribute.class);
      PositionIncrementAttribute posAtt = stream.addAttribute(PositionIncrementAttribute.class);
      stream.reset();
      while (stream.incrementToken()) {
        BytesRef term = BytesRef.deepCopyOf(bytesAtt.getBytesRef());
        int increment = posAtt.getPositionIncrement();
        if (increment > 1) {
          int precedingSpaces = increment - 1;
          if (precedingSpaces == 1) {
            assembled.add(new ExtendedIntervalsSource(new TermIntervalsSource(term), 1, 0));
          } else {
            assembled.add(
                new ExtendedIntervalsSource(
                    new TermIntervalsSource(term), precedingSpaces, 0));
          }
        } else if (increment == 1) {
          assembled.add(new TermIntervalsSource(term));
        } else {
          assembled.add(
              new ExtendedIntervalsSource(new TermIntervalsSource(term), increment - 1, 0));
        }
      }
      stream.end();
    }

    if (assembled.size() == 0) {
      return NO_INTERVALS;
    }
    if (assembled.size() == 1) {
      return assembled.get(0);
    }

    if (maxGaps == 0 && ordered) {
      return BlockIntervalsSource.build(assembled);
    }

    IntervalsSource inner;
    if (ordered) {
      List<IntervalsSource> flattened = new ArrayList<>();
      for (int i = 0; i < assembled.size(); i++) {
        IntervalsSource source = assembled.get(i);
        if (source instanceof OrderedIntervalsSource) {
          flattened.addAll(((OrderedIntervalsSource) source).subSources);
        } else {
          flattened.add(source);
        }
      }
      List<IntervalsSource> deduplicated = new ArrayList<>();
      List<IntervalsSource> current = new ArrayList<>();
      for (int i = 0; i < flattened.size(); i++) {
        IntervalsSource source = flattened.get(i);
        if (current.size() == 0 || current.get(0).equals(source)) {
          current.add(source);
        } else {
          IntervalsSource repeating =
              RepeatingIntervalsSource.build(current.get(0), current.size());
          deduplicated.add(repeating);
          current.clear();
          current.add(source);
        }
      }
      if (current.size() > 0) {
        deduplicated.add(RepeatingIntervalsSource.build(current.get(0), current.size()));
      }
      if (deduplicated.size() == 1 && deduplicated.get(0) instanceof RepeatingIntervalsSource) {
        ((RepeatingIntervalsSource) deduplicated.get(0)).setName("ORDERED");
      }
      if (deduplicated.size() == 1) {
        inner = deduplicated.get(0);
      } else {
        inner = new OrderedIntervalsSource(deduplicated);
      }
    } else {
      List<IntervalsSource> flattened = new ArrayList<>();
      for (int i = 0; i < assembled.size(); i++) {
        IntervalsSource source = assembled.get(i);
        if (source instanceof UnorderedIntervalsSource) {
          flattened.addAll(((UnorderedIntervalsSource) source).subSources);
        } else {
          flattened.add(source);
        }
      }
      Map<IntervalsSource, Integer> counts = new LinkedHashMap<>();
      for (int i = 0; i < flattened.size(); i++) {
        IntervalsSource source = flattened.get(i);
        Integer prev = counts.get(source);
        if (prev == null) {
          counts.put(source, 1);
        } else {
          counts.put(source, prev + 1);
        }
      }
      List<IntervalsSource> deduplicated = new ArrayList<>();
      for (IntervalsSource source : counts.keySet()) {
        deduplicated.add(RepeatingIntervalsSource.build(source, counts.get(source)));
      }
      if (deduplicated.size() == 1 && deduplicated.get(0) instanceof RepeatingIntervalsSource) {
        ((RepeatingIntervalsSource) deduplicated.get(0)).setName("UNORDERED");
      }
      if (deduplicated.size() == 1) {
        inner = deduplicated.get(0);
      } else {
        inner = new UnorderedIntervalsSource(deduplicated);
      }
    }

    if (maxGaps == -1) {
      return inner;
    }
    return FilteredIntervalsSource.maxGaps(inner, maxGaps);
  }

  static final IntervalsSource NO_INTERVALS =
      new IntervalsSource() {
        @Override
        public IntervalIterator intervals(String field, LeafReaderContext ctx) {
          return new IntervalIterator() {
            @Override
            public int start() {
              return NO_MORE_INTERVALS;
            }

            @Override
            public int end() {
              return NO_MORE_INTERVALS;
            }

            @Override
            public int gaps() {
              throw new UnsupportedOperationException();
            }

            @Override
            public int nextInterval() {
              return NO_MORE_INTERVALS;
            }

            @Override
            public float matchCost() {
              return 0;
            }

            @Override
            public int docID() {
              return NO_MORE_DOCS;
            }

            @Override
            public int nextDoc() {
              return NO_MORE_DOCS;
            }

            @Override
            public int advance(int target) {
              return NO_MORE_DOCS;
            }

            @Override
            public long cost() {
              return 0;
            }
          };
        }

        @Override
        public IntervalMatchesIterator matches(String field, LeafReaderContext ctx, int doc) {
          return null;
        }

        @Override
        public void visit(String field, QueryVisitor visitor) {}

        @Override
        public int minExtent() {
          return 0;
        }

        @Override
        public Collection<IntervalsSource> pullUpDisjunctions() {
          return Collections.emptyList();
        }

        @Override
        public int hashCode() {
          return 0;
        }

        @Override
        public boolean equals(Object other) {
          return other == this;
        }

        @Override
        public String toString() {
          return "no_match";
        }
      };
}

