    iw.addDocument(d);
    iw.commit();
    iw.close();
    IndexReader ir = DirectoryReader.open(dir);
    IndexSearcher is = new IndexSearcher(ir);

    // "x x" analyzes to nothing -> NO_INTERVALS source
    IntervalQuery empty = new IntervalQuery("f", Intervals.phrase(1, Intervals.term("x"), Intervals.term("x")));
    BooleanQuery bq =
        new BooleanQuery.Builder()
            .add(new MatchAllDocsQuery(), BooleanClause.Occur.FILTER)
            .add(empty, BooleanClause.Occur.FILTER)
            .build();

    ScoreDoc[] hits = is.search(bq, 10).scoreDocs;
