import org.apache.lucene.analysis.core.WhitespaceAnalyzer;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.Field;
import org.apache.lucene.document.TextField;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.queries.intervals.Intervals;
import org.apache.lucene.queries.intervals.IntervalQuery;
import org.apache.lucene.search.BooleanClause;
import org.apache.lucene.search.BooleanQuery;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.MatchAllDocsQuery;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

public class Repro {
  public static void main(String[] args) throws Exception {
    Directory dir = new ByteBuffersDirectory();
    IndexWriter iw = new IndexWriter(dir, new IndexWriterConfig(new WhitespaceAnalyzer()));
    Document d = new Document();
    d.add(new TextField("f", "a b c", Field.Store.NO));
    iw.addDocument(d);
    iw.commit();
    iw.close();
    IndexReader ir = DirectoryReader.open(dir);
    IndexSearcher is = new IndexSearcher(ir);

    // "x x" analyzes to nothing -> NO_INTERVALS source
    IntervalQuery empty = new IntervalQuery("f", Intervals.phrase(Intervals.term("x"), Intervals.term("x")));
    IntervalQuery nonEmpty = new IntervalQuery("f", Intervals.phrase(Intervals.term("a"), Intervals.term("b")));

    run(is, "MUST(empty)+FILTER(all)", new BooleanQuery.Builder()
        .add(empty, BooleanClause.Occur.MUST)
        .add(new MatchAllDocsQuery(), BooleanClause.Occur.FILTER)
        .build());
    run(is, "FILTER(empty)+FILTER(all)", new BooleanQuery.Builder()
        .add(empty, BooleanClause.Occur.FILTER)
        .add(new MatchAllDocsQuery(), BooleanClause.Occur.FILTER)
        .build());
    run(is, "MUST(nonEmpty)+MUST(empty)", new BooleanQuery.Builder()
        .add(nonEmpty, BooleanClause.Occur.MUST)
        .add(empty, BooleanClause.Occur.MUST)
        .build());
    run(is, "MUST(nonEmpty)+FILTER(empty)", new BooleanQuery.Builder()
        .add(nonEmpty, BooleanClause.Occur.MUST)
        .add(empty, BooleanClause.Occur.FILTER)
        .build());

    ir.close();
    dir.close();
  }

  static void run(IndexSearcher is, String name, BooleanQuery bq) {
    try {
      ScoreDoc[] hits = is.search(bq, 10).scoreDocs;
      System.out.println(name + ": OK, hits=" + hits.length);
    } catch (Throwable t) {
      System.out.println(name + ": EXCEPTION " + t);
    }
  }
}

